        class MyClass:
            @classmethod
            def from_crawler(cls, crawler, *args, **kwargs):
                return cls(*args, **kwargs)

            def __init__(self, arg1, arg2):
                self.arg1 = arg1
                self.arg2 = arg2

        instance = build_from_crawler(MyClass, self.crawler, "value1", "value2")
        assert instance.arg1 == "value1"
        assert instance.arg2 == "value2"

    def test_build_from_crawler_without_from_crawler_method(self) -> None:
        class MyClass:
            def __init__(self, arg1, arg2):
                self.arg1 = arg1
                self.arg2 = arg2

        instance = build_from_crawler(MyClass, self.crawler, "value1", "value2")
        assert instance.arg1 == "value1"
        assert instance.arg2 == "value2"

    def test_build_from_crawler_with_none_return(self) -> None:
        class MyClass:
            @classmethod
            def from_crawler(cls, crawler, *args, **kwargs):
                return None

        with pytest.raises(TypeError) as excinfo:
            build_from_crawler(MyClass, self.crawler)
        assert str(excinfo.value) == "MyClass.from_crawler returned None"

    def test_build_from_crawler_with_not_configured_exception(self) -> None:
        class MyClass:
            @classmethod
            def from_crawler(cls, crawler, *args, **kwargs):
                raise NotConfigured

        with pytest.raises(NotConfigured):
            build_from_crawler(MyClass, self.crawler)

    def test_build_from_crawler_with_value_error(self) -> None:
        class MyClass:
            @classmethod
            def from_crawler(cls, crawler, *args, **kwargs):
